"use client";

import { generateTruthTable } from "@/lib/logic";
import { ui } from "@/lib/uiStyles";

/** Truth table that is generated by evaluating the gate and highlights the
 * row matching the live inputs. */
export default function LiveTruthTable({
  gateType,
  currentInputA,
  currentInputB,
  title = "LIVE TRUTH TABLE",
}: {
  gateType: string;
  currentInputA: number;
  currentInputB?: number;
  title?: string;
}) {
  const key = (gateType || "").toUpperCase();
  const oneInput = key === "NOT" || key === "BUFFER";
  const rows = generateTruthTable(key);

  return (
    <div className="flex flex-col gap-1">
      <p className="text-xs font-black tracking-widest">{title}</p>
      <table className={ui.table}>
        <thead>
          <tr>
            <th>A</th>
            {!oneInput && <th>B</th>}
            <th className={ui.tableOutputHeader} data-output>Y</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => {
            const match =
              row.a === currentInputA &&
              (oneInput || row.b === (currentInputB ?? 0));
            return (
              <tr key={idx} className={match ? `${ui.rowActive} ${ui.rowActiveOutput}` : ""}>
                <td>{row.a}</td>
                {!oneInput && <td>{row.b}</td>}
                <td className={ui.tableOutput} data-output>{row.y}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
